begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
-- Synthetic identities/codes only. Everything rolls back after testing.
insert into auth.users (id, email, email_confirmed_at, raw_user_meta_data)
select ('00000000-0000-4000-8000-' || lpad(i::text, 12, '0'))::uuid,
  'rls-' || i || '@example.test', now(), '{"role":"admin","status":"active"}'::jsonb
from generate_series(1,9) i;
select is((select count(*)::int from public.profiles where id::text like '00000000-%' and role = 'pending' and status = 'pending'),9,'metadata cannot grant privileges');
update public.profiles set role = case right(id::text,1)
  when '2' then 'viewer'::public.user_role when '3' then 'field_officer'::public.user_role
  when '4' then 'coordinator'::public.user_role when '5' then 'admin'::public.user_role
  else 'viewer'::public.user_role end, status='active' where id::text like '00000000-%' and right(id::text,1) <> '1';
update public.profiles set status='suspended' where id::text like '00000000-%' and right(id::text,1)='6';
update auth.users set email_confirmed_at=null where id::text like '00000000-%' and right(id::text,1)='7';
update auth.users set is_anonymous=true where id::text like '00000000-%' and right(id::text,1)='8';
insert into public.profile_district_grants(user_id,district_code,granted_by)
select id, 'TEST-A', '00000000-0000-4000-8000-000000000005' from public.profiles where id::text like '00000000-%' and right(id::text,1)<>'9';
-- An RLS probe, not an operational table or real geography.
create table public.test_scope_probe (id int primary key, district_code text);
insert into public.test_scope_probe values (1,'TEST-A'), (2,'TEST-B');
alter table public.test_scope_probe enable row level security;
grant select on public.test_scope_probe to anon, authenticated;
create policy scoped_read on public.test_scope_probe for select to authenticated using (public.can_access_district(district_code));
set local role anon;
select is((select count(*)::int from public.test_scope_probe),0,'anon sees no area records');
select throws_ok('select * from public.profiles','42501',null,'anon has no profile grant');
select throws_ok($$select public.can_access_district('TEST-A')$$,'42501',null,'anon cannot execute area helper');
reset role;

set local role authenticated;
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000001',true);
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000000001","role":"authenticated","user_metadata":{"role":"admin"}}',true);
select is((select count(*)::int from public.test_scope_probe),0,'pending: scoped rows');
select is(public.can_access_district('TEST-B'),false,'pending: denied outside area');
select is((select count(*)::int from public.profiles where id::text like '00000000-%'),1,'pending: profile visibility');
select throws_ok($$update public.profiles set role='admin' where id='00000000-0000-4000-8000-000000000001'$$,'42501',null,'pending: cannot promote self');
select throws_ok($$update public.profiles set status='active' where id='00000000-0000-4000-8000-000000000001'$$,'42501',null,'pending: cannot approve self');
select throws_ok($$insert into public.profile_district_grants values ('00000000-0000-4000-8000-000000000001','TEST-B','00000000-0000-4000-8000-000000000001',now())$$,'42501',null,'pending: cannot grant area');
select throws_ok($$delete from public.access_audit_logs$$,'42501',null,'pending: cannot delete audit');
select throws_ok($$select public.set_account_access('00000000-0000-4000-8000-000000000001','viewer','active',array['TEST-A'],'Test approval reason')$$,'42501',null,'non-admin cannot approve others');
reset role;
set local role authenticated;
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000002',true);
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000000002","role":"authenticated","user_metadata":{"role":"admin"}}',true);
select is((select count(*)::int from public.test_scope_probe),1,'viewer: scoped rows');
select is(public.can_access_district('TEST-B'),false,'viewer: denied outside area');
