select is(public.can_access_district('TEST-B'),false,'admin: denied outside area');
select is((select count(*)::int from public.profiles where id::text like '00000000-%'),9,'admin: profile visibility');
select throws_ok($$update public.profiles set role='admin' where id='00000000-0000-4000-8000-000000000005'$$,'42501',null,'admin: cannot promote self');
select throws_ok($$update public.profiles set status='active' where id='00000000-0000-4000-8000-000000000005'$$,'42501',null,'admin: cannot approve self');
