set local role authenticated;
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000002',true);
select lives_ok($$update public.profiles set display_name='Local staff' where id=auth.uid()$$,'own display name can change');
update public.profiles set display_name='Other' where id='00000000-0000-4000-8000-000000000003';
reset role;
select isnt((select display_name from public.profiles where id='00000000-0000-4000-8000-000000000003'),'Other','cannot edit other profiles');
set local role authenticated;
select is((select count(*)::int from public.access_audit_logs),0,'viewer cannot read audit');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000005',true);
select throws_ok($$select public.set_account_access(auth.uid(),'admin','active',array['TEST-B'],'Test self change')$$,'42501',null,'admin cannot change own grants');
select throws_ok($$select public.set_account_access('00000000-0000-4000-8000-000000000001','viewer','active',array['TEST-A'],'')$$,'22023',null,'approval requires rationale');
select throws_ok($$select public.set_account_access('00000000-0000-4000-8000-000000000007','viewer','active',array['TEST-A'],'Test approval reason')$$,'22023',null,'unconfirmed account cannot activate');
select lives_ok($$select public.set_account_access('00000000-0000-4000-8000-000000000001','viewer','active',array['TEST-A','TEST-A'],'Local test approval reason')$$,'admin can approve verified staff');
select is((select count(*)::int from public.access_audit_logs),1,'approval creates audit event');
select is((select before_state->>'role' from public.access_audit_logs),'pending','audit preserves previous role');
select is((select count(*)::int from public.profile_district_grants where user_id='00000000-0000-4000-8000-000000000001'),1,'duplicate grants collapse');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000001',true);
select is((select count(*)::int from public.test_scope_probe),1,'approved staff receive scoped access');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000005',true);
select lives_ok($$select public.set_account_access('00000000-0000-4000-8000-000000000001','viewer','suspended',array[]::text[],'Local test suspension reason')$$,'admin can revoke access');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000001',true);
select is((select count(*)::int from public.test_scope_probe),0,'revocation applies with same JWT');
reset role;
select throws_ok($$update public.access_audit_logs set reason = 'Tampering with history'$$,'42501',null,'audit rejects owner modification');
